local H={}
H.stations={loom={'Loom','Tailoring 4: weave 5 Wool Thread into a Cloth Strip. Dye strips here to make coloured cloth.'},smelter={'Smelter','Smelt copper or iron chunks into bars. Iron requires Smithing 10; large iron chunks require 19. Carry Copper Tongs or Iron Tongs.'},anvil={'Anvil','Forge copper or iron equipment. Copper recipes require Smithing 1-9; Iron recipes require 10-19. Steel armor, sword and shield unlock at Smithing 20-29; other later items are Not in yet. Carry the hammer shown by the recipe.'},woodcraft={'Woodworking / Fletching','Open Fletching from the skill panel, or use a Copper Knife or Copper Dagger on logs. Poplar Bow and Snake Fang Arrows require Fletching 30.'},spinningWheel={'Spinning Wheel','Turn fibers into strings, wool into thread, and thread into cloth.'},alchemy={'Alchemy Table','Combine ingredients into potions and remedies.'},sewing={'Sewing','Use the Tailor Table for cloth recipes and mage clothing.'},stove={'Stove','Cook raw food. Cooking level affects burning and food grade.'},campfire={'Campfire','Cook raw food. Campfires burn food more often than stoves.'},leathercraft={'Leatherworking','Right-click a Needle and choose Use to open recipes; all leather sizes are supported.'},inscription={'Inscription Table','Make all six spell pages and Melee, Ranged and Magic Skill Pages using Pen & Ink. Magic Skill Page requires Inscription 8, an Empty Spell Page and one blessed Green Slime Tube.'},tailoring={'Tailoring','Spin, weave, dye and sew. Open this menu from Skills > Tailoring. A wheel or loom is required for station recipes; a Needle is required for clothing.'},tanningVat={'Tanning Vat','Leatherworking 3: click nearby to load raw hides. Two normal hides fit; one large or extra-large hide needs the entire empty vat. Collect soaked hides from the ground when ready. Completion awards 5 Leatherworking XP (before race bonus).'},hideStretcher={'Hide Stretcher','Leatherworking 3: click nearby to dry exactly one soaked hide of any type (normal, large, extra-large or cave snake). Wait, then click again to collect matching leather. Completion awards 10 Leatherworking XP (before race bonus).'},magicAltar={'Magic Altar','The altar remains in the world, but the old player magic system has been removed for rebuilding.'},socketTable={'Socket Table','Select bag equipment, then Create Socket with a Chisel. Failures permanently break a position. Insert cut gems into open positions without a failure roll. Enchant gems for bonuses.'},enchantAltar={'Enchanting Altar','Select a cut Ruby, Sapphire, Emerald or Onyx and a Skill/Spell Page, then use matching gem dust. Skill pages add effective combat levels; spell pages add attack/spell damage or healing.'}}
H.skills={Prospecting="Right-click an ore node nearby to identify it. No tool or level requirement. Higher levels identify ore faster; each newly identified node awards Prospecting XP.",Woodworking="Use a Copper Knife or Dagger on logs. Make shafts, rods, torches and wooden parts.",Mining='Mine ore with a Copper Pickaxe.',Woodcutting='Chop pine with a Copper Axe; oak requires level 11.',Smithing='Smelt bars and forge equipment.',['Melee Combat']='Fight with melee weapons. Levels 2-8 unlock active abilities; open the skill guide and drag unlocked abilities to the melee weapon hotbar.',Ranged='Equip a bow and ammunition; click an enemy in range.',Strength='Train through physical combat. Increases bag capacity at level milestones.',Agility='Train through stamina use and combat.',Health='Train in combat to raise maximum health.',Skinning='Use a Copper Dagger or Copper Knife on a defeated animal. Up to 10 levels below its Skinning requirement, recover exactly 1 matching meat and 1 Torn Hide (cook into jerky), with reduced XP. More than 10 levels below cannot skin it.',Leatherworking='Soak and stretch hides, then use a Needle on leather.',Fletching='Spin hemp or flax into bowstring; make bows and assemble arrows. Woodworking makes shafts. Gathering hemp/flax grants no XP.',Alchemy='Gather alchemy plants and make remedies.',Fishing='Use poles on shoreline water: Oak 5, Poplar 20. Swordfish at Fishing 40 with a Pine pole or better. Right-click an empty Shrimp Pot (6), Crab Pot (12) or Lobster Pot (30), select Place, then left-click a green shoreline preview. Placement and recovery take 2 seconds. Catch odds rise with Fishing and time; Shrimp capacity rises from 1 at Fishing 6 to 15 at 20; other pots hold 10. Shrimp/Crab catch checks take 60 seconds. Exact counts unlock at Fishing 50. Placed pots are lost on logout. Left-click your placed pot to recover; right-click Empty in inventory drops catches. Break all matching shellfish in inventory with a knife at Cooking 12/30; harvest parts for 1-5 raw meat. Cooked meats can use the potion belt.',Cooking='Cook at a stove or campfire. Levels improve grades and reduce burns.',['Jewel Crafting']='Merged Crafting and Jewel Cutting. Onyx at 1; Ruby at 10; Sapphire at 20; Emerald at 30. Socket positions: 2 at 1, 3 at 20, 4 at 40, 5 at 50, 6 at 60. Guaranteed extraction at 70. Use a Chisel and Copper Hammer on jewel-bearing rocks and rough gems. Create permanent open/broken sockets with a Chisel at the Socket Table, then insert cut gems. Insertion is guaranteed. Rough Onyx becomes Cut Onyx; Cut Onyx can be carved into 3 Void rune materials.',Enchanting='Enchant cut gems with pages and matching dust.',Inscription='Make pages at the Inscription Table using Pen & Ink.',Tailoring='Open Tailoring from this skill guide. Spin Wool at a Spinning Wheel; weave and dye Cloth Strips at a Loom. Sew clothing with a Needle. Cape and hood recipes preserve the colour of their cloth.',Commanding='Recruit and fight with mercenaries to unlock more band slots.',Firemaking='Use Flint and Steel on logs to create a campfire. At level 10 this creates a Bonfire using one log. Right-click logs > Add to Bonfire to add one log per 2-second cast; this repeats until you move, press Escape, run out of logs, or the fire goes out. Each log burns for 20 real seconds, even while paused, away, or logged out, and yields 5 Charred Wood. Bonfires grant +20% maximum Health and Defence for 5 minutes after leaving; the flame icon shows buff time. Adding fuel refreshes the buff. Oak logs award more Firemaking XP than pine.',Fieldcraft='Camp Fire unlocks at 2. Rest awards 20 base XP on the same 5-minute cooldown. Skill actions within 100 units of your camp contribute 10% of earned XP (up to 5 base Fieldcraft XP per gain).',Religion='Carve Feathers with a Copper Knife or Dagger for 4 base Religion XP. Bless rune materials to gain Religion XP. A Religion Altar blesses all eligible inventory materials and awards 2x blessing XP, per item without a blessing action cap. Passive milestones at levels 1, 10, 20, 30, 40, 50, 60, 75, 90 and 99 increase physical/spell damage, physical protection and rune preservation, with slower physical attacks as a tradeoff. Hover each tier for exact effects. Tier totals replace earlier tiers.'}
H.stations.religionAltar={'Religion Altar','Click within 55 units to bless unblessed rune materials in your inventory. Awards 2x Religion XP, per item without a blessing action cap. Already blessed materials give no repeat XP. Material grades are preserved. Blessing requires Religion equal to the matching spell Magic level (Fire 1, Water 2, Earth 3, Air 4, Void 5, Healing 6).'}
H.stations.metalLoom={'Metal Weaving Loom','Tailoring 30: weave 2 Iron Bars + 5 Wool Thread into Iron Weave Thread. Make Magic Weave Iron Boots (30), Hat (32), and Robes (35) here with a Needle.'}
local special={['Copper Axe']='Carry or equip, then click a tree nearby to chop.',['Copper Pickaxe']='Carry or equip, then click ore nearby to mine.',['Copper Dagger']='Right-click > Use, then click logs for woodworking or a fish to fillet it. Also needed for hemp and skinning.',['Copper Knife']='Starting utility knife. Has no combat stats and can perform the same skill/crafting tasks as a Copper Dagger.',['Needle']='Right-click > Use on cloth to open Tailoring, or open Skills > Tailoring > Open Tailoring. A Needle is required for sewing.',['Flint and Steel']='Right-click > Use to light an equipped Torch; otherwise click bag logs to create a campfire.',['Bow String']='Right-click > Use on an unstrung bow. Requires Fletching 6 for pine or 12 for oak.',['Copper Arrowheads']='Fletching 2: right-click > Use, then click arrow shafts in a bag.',['Chisel']='Right-click > Use, then click a jewel-bearing rock or rough jewel in a bag.',['Blue Dye']='Tailoring 3: Empty Tube + Large Blue Mushroom. Dye a Cloth Strip at a Loom at Tailoring 5.',['Fishing Pole']='Carry or equip; click shoreline water nearby to fish. Walking away or full bags stops fishing.',['Shears']='Carry Shears in a bag or equip them, then click a woolly sheep nearby.',['Raw Hide']='Click a Tanning Vat to soak, then stretch the soaked hide.',['Extra Large Raw Hide']='Needs an empty Tanning Vat and occupies both slots. Stretch the soaked hide afterward.',['Soaked Hide']='Click a Hide Stretcher to load; wait, then click to collect leather.',['Extra Large Soaked Hide']='Click a Hide Stretcher to load; wait, then click to collect extra-large leather.',['Quiver']='Equip in AMMO, then right-click arrows > Load Quiver. Holds one arrow type. Unload before dropping or banking.',['Copper Arrows']='Right-click > Equip Ammo, or Load Quiver when one is equipped. Bows consume one per shot.',['Iron Arrowheads']='Fletching 20: Use on any arrow shaft while carrying a Feather to make an Iron Arrow.',['Iron Arrows']='Right-click > Equip Ammo, or load into a Quiver. Iron arrows add +1 damage to bow shots.',['Iron Tongs']='Required to smelt iron chunks into Iron Bars.',['Iron Hammer']='Required to forge iron-tier equipment at the Anvil.',['Torch']='Equip in OFFHAND, then use Flint and Steel to light it.',['Lit Torch']='Lights your surroundings. Unequipping extinguishes it.',['Egg']='Collect near chickens; store or sell. No cooking recipe is implemented yet.',['Bronze Bar']='Legacy material: no bronze crafting recipe is currently available. Store or sell it.'}
special['Bronze bar']=special['Bronze Bar']
special['Tin ore']='Store or sell. No tin smelting recipe is currently implemented.'
special['Basic Wood Parts']='Legacy handles; old saves convert these to Pine Wood Parts.'
special['Logs']='Legacy logs; old saves convert these to Pine Logs. Use a knife on logs for woodworking.'
special['Large Raw Leather']='Large boar hide: occupies the entire empty Tanning Vat. Stretch after soaking.'
special['Large Soaked Leather']='Click a Hide Stretcher to load; wait, then click to collect Large Leather.'
special['Large Leather']='Finished boar leather. Store or sell; no crafting recipe currently consumes this size.'
function H.tip(title,detail,typ) return {item={name=title,qty=1},info={title=title,type=typ or 'How to use',detail=detail}} end
function H.build(ui)
 local uses={}
 for st in pairs(H.stations) do for _,r in ipairs(ui.crafting:getRecipes(st)) do for _,n in ipairs(r.needs) do uses[n[1]]=uses[n[1]] or {};uses[n[1]][H.stations[st][1]]=true end end end
 ui.itemHelp={}
 for name in pairs(ui.sprites.itemImages) do
  local info=ui.sprites.itemInfo[name] or {title=name,type='Item',detail=''};ui.sprites.itemInfo[name]=info
  local t=info.type;local parts={}
  if name=='Unstrung Fishing Rod' then parts[1]='At Woodworking 1, use the Woodworking menu to combine this with Rawhide String into a Fishing Pole.'
  elseif special[name] then parts[1]=special[name]
  elseif name:find('Arrow Shafts',1,true) then parts[1]='Woodworking makes these shafts. At Fletching 2, use Copper Arrowheads on them to assemble arrows.'
  elseif name:find('Unstrung Bow',1,true) then parts[1]='Use Bow String on this bow. Stringing requires Fletching '..(name:find('Oak',1,true) and '12' or '6')..'.'
  elseif name:find('-bearing Rock',1,true) or name:match('^Rough ') then parts[1]='Carry a Copper Hammer. Right-click a Chisel > Use, then click this item. Failure can turn it into dust.'
  elseif name=='Large Fish' then parts[1]='Fishing 7. Cooking 7: use Copper Knife or Copper Dagger for 2-5 raw fillets, scaled by Cooking.'
  elseif name=='Small Fish' or name=='Eel' then parts[1]='Cooking 7: use Copper Knife or Copper Dagger on this fish to make raw fillets.'
  elseif t=='Weapon' or t=='Tool' or t=='Head Armor' or t=='Body Armor' or t=='Foot Armor' or t=='Cape' or t=='Offhand' then parts[1]='Right-click in a bag > Equip. Right-click equipped gear to remove it.'
  elseif t=='Food' or t=='Burnt Food' then parts[1]='Right-click in a bag > Eat to restore health.'
  elseif t=='Potion' then parts[1]='Right-click > Equip Potion, or drag to the potion belt. Press F1-F4 to drink; left-click a belt slot to drink, or right-click to return it to your bag.'
  elseif t=='Skill Page' then parts[1]='Select at the Enchanting Altar to add its skill to a cut gem.'
  elseif t=='Cut Jewel' then parts[1]='Use the Socket Table to place in equipment, or enchant it first at the Enchanting Altar.'
  elseif t=='Gem Dust' then parts[1]='Select a matching cut gem and page at the Enchanting Altar, then right-click this dust.'
  elseif ui.inv:isBagItem(name) then parts[1]='Right-click > Equip Bag; requires a free bag slot. Open bags from the bag bar or press I.'
  elseif ui.inv:isCurrency(name) then parts[1]='Spent automatically in shops. 100 copper = 1 silver; 100 silver = 1 gold.' end
  if t=='Weapon' or t=='Head Armor' or t=='Body Armor' or t=='Foot Armor' or t=='Cape' or t=='Offhand' then local skill,level=require('game.progression').requirement(name,info);parts[#parts+1]=info.unrestricted and 'Anyone can equip: no skill or level requirement.'or(require('game.iron_gear').items[name]or require('game.advanced_gear').items[name]) and ('Equip requirement: '..skill..' level '..level..' for player and mercenaries.') or ('Players can use purchased gear immediately. Mercenary requirement: '..skill..' level '..level..'.') end
  if uses[name] then local a={};for st in pairs(uses[name]) do a[#a+1]=st end;table.sort(a);parts[#parts+1]='Ingredient at: '..table.concat(a,', ')..'. Hover recipes for requirements.' end
  if #parts==0 then parts[1]='Keep for its described use or store in the bank. Right-click to see available actions.' end
  if ui.inv:isStackable(name) and ui.inv:maxStack(name)<=100 then parts[#parts+1]='Stacks to '..ui.inv:maxStack(name)..' per bag slot.' end
  ui.itemHelp[name]=table.concat(parts,'\n')
 end
end
function H.enrich(ui,it,info)
 if ui.inv:isBagItem(it.name)then local out={};for k,v in pairs(info)do out[k]=v end;out.detail=(out.detail or'')..'\nRight-click to equip in a free slot, or drag onto any bag slot to replace it safely. Right-click an equipped bag to unequip.';return out end
 if not ui.itemHelp then H.build(ui) end
 if not ui.itemHelp[it.name] then return info end
 local out={};for k,v in pairs(info) do out[k]=v end
 out.detail=(info.detail or '')..'\n'..ui.itemHelp[it.name];if it.name=='Pine Staff' then out.detail=out.detail..string.format('\nYour rune-saving chance: %.1f%%.',require('game.staff_effects').chance('Pine Staff',ui.skills:get('Magic').level)*100) end;return out
end
function H.recipe(ui,station,r)
 local a={'Click to craft. Costs 2 stamina.',string.format('%s: +%g XP. Duration: %.1fs. Moving cancels.',r.skill,(r.xp or 0)*ui.skills:xpMultiplier(r.skill),(r.duration or .5)*math.max(1,r.qty or 1))};for _,n in ipairs(r.needs) do a[#a+1]=n[2]..'x '..n[1]..' (have '..ui.inv:countItem(n[1])..')' end
 if r.tool then a[#a+1]='Tool: '..r.tool..' (carried or equipped).' end
 a[#a+1]='Your '..r.skill..' level: '..ui.skills:get(r.skill).level
 if r.level then a[#a+1]='Requires '..(r.skill or 'Leatherworking')..' level '..r.level..'.' end
 a[#a+1]=(station=='stove' or station=='campfire') and ('Result: cooked grade A-D or burnt food. '..(station=='campfire' and 'Higher burn chance than a stove.' or 'Lower burn chance than a campfire.')) or ('Produces '..(r.qty or 1)..'x '..r.output..' with a rolled quality grade Dâ€“A. Higher skill improves grade odds.')
 for _,n in ipairs(r.byproducts or {}) do a[#a+1]='Also returns '..n[2]..'x '..n[1]..'.' end
 return H.tip(r.name,table.concat(a,'\n'),'Recipe')
end
local function inside(mx,my,x,y,w,h) return mx>=x and my>=y and mx<x+w and my<y+h end
local panels={runeBag='Rune Bag capacity per material: D 50, C 60, B 70, A 80. Bag spell strength: D 100%, C 105%, B 110%, A 115%, multiplied by rune-material quality.',equipment='Right-click bag gear to equip; right-click equipped gear to remove it.',skills='Select a tab, then click a skill for its level-by-level unlock guide. Scroll for more.',bank='Left-click bag items to deposit while the bank is open. Click stored stacks to withdraw one. Right-click stored items for Withdraw, Withdraw 10, or Withdraw 100. Drag between bank slots to sort. Use numbered tabs for expanded storage.',shop='Select stock, then Buy Max to buy as many as your coins, stock and bags allow. Double-click buys one. Sell Inventory sells accepted carried goods; loaded containers remain protected.',spellbook='At the Magic Altar, add crafted Spell Pages to the Spellbook. Equip the Spellbook offhand to show its movable casting hotbar. Casting consumes blessed rune materials from the Rune Bag first, then inventory.',mercenary='Click a role to recruit, then select a companion. Commanding limits band size.',mercBand='Click tabs to select. Right-click tabs to fire, or equipment rows to unequip. Right-click bag gear > Give to Merc.',bankClerk='Buy 25 additional bank slots for 1 gold. Each expansion adds another bank tab, up to 250 slots.'}
function H.ui(ui,mx,my,w,h)
 if not ui.inputPanel and require('game.abilities').hasWeapon(ui) then local si=ui:weaponHotbarSlotAt(mx,my,w,h);if si then local bar=ui:currentWeaponHotbar();local n=bar and bar[si];if n then local a=require('game.abilities').byName(n);if a then return H.tip(a.name,a.desc..' Cooldown: '..tostring(a.cooldown)..'s.','Melee Ability - slot '..si),true end end;local cat=require('game.abilities').weaponCategory(ui);local detail=cat=='melee' and 'Drag an unlocked Melee Combat ability here from the skill guide. Right-click an assigned ability or drag it off the hotbar to remove it.' or 'This ranged weapon has its own hotbar. Right-click an assigned ability or drag it off the hotbar to remove it.';return H.tip('Weapon Ability Slot',detail,'Weapon Hotbar'),true end end
 local function bagTip(bi,si)
  local bag=bi and ui.inv:getBag(bi);local it=bag and bag.slots[si or 0]
  if it and ui.open.shop and ui.shop:acceptsSale(it.name) and not ui.inv:isCurrency(it.name) then return {item=it,info={title=it.name,type='Inventory',detail='Sell to this shop: '..ui:priceText(ui.shop:sellPrice(it.name))..'. Right-click for actions.'}} end
  return it and {item=it} or H.tip('Inventory','Right-click items for actions. Drag items between slots. Drag the title bar to move the window.')
 end
 if ui.bagnonMode then local any=false;for i=1,ui.inv:bagSlotCount()do any=any or ui.bagOpen[i] end;if any and inside(mx,my,ui:combinedRect()) then local bi,si=ui:combinedSlotAt(mx,my);return bagTip(bi,si),true end
 else for bi=ui.inv:bagSlotCount(),1,-1 do if ui.bagOpen[bi] and ui.inv:getBag(bi) and inside(mx,my,ui:bagWindowRect(bi)) then return bagTip(bi,ui:slotAt(mx,my,bi)),true end end end
 for i=#ui.zOrder,1,-1 do local name=ui.zOrder[i]
  if name~='inventory' and ui.open[name] and inside(mx,my,ui:rect(name)) then
   local x,y,pw,ph=ui:rect(name)
   if inside(mx,my,x+pw-28,y,28,28) then return H.tip('Close','Click X to close this window.'),true end
   if my<y+28 then return H.tip(name,'Resize with the bottom-right corner. Drag the title bar to move this window.'),true end
   if name=='shop' then local si=ui:shopSlotAt(mx,my);local row=si and ui.shop.slots[si];if row then return {item=row.object or row,info={title=row.name,type='Shop stock x'..row.qty,detail='Right-click to buy. Buy: '..ui:priceText(ui.shop:buyPrice(row.name))..(ui.shop:acceptsSale(row.name) and (' | Sell: '..ui:priceText(ui.shop:sellPrice(row.name))) or ' | This shop does not buy this item.')}},true end end
   if name=='bank' then local si=ui:bankSlotAt(mx,my);local it=si and ui.inv.bank[si];if it then return {item=it,info={title=it.name,type='Bank storage',detail='Click to withdraw this stack.'}},true end end
   if name=='equipment' then local socketTip=require('game.sockets').hoverEquipment(ui,mx,my);if socketTip then return socketTip,true end;local slot=ui:equipmentSlotAt(mx,my);if slot then local it=ui.equipment[slot];return it and {item=require('game.items').equipped(ui,slot)} or H.tip(slot:upper()..' slot','Right-click compatible bag gear to equip it here.'),true end end
   if name=='skills' and ui.hoverTooltip then return ui.hoverTooltip,true end
   if name=='mercenary' then
    for ri,role in ipairs({'Tank','Healer','Ranged'}) do if inside(mx,my,x+16+(ri-1)*118,y+66,108,30) then
     local desc=role=='Tank' and 'Fights at close range. Give armor and a weapon through the bag menu.' or role=='Healer' and 'Restores health periodically. Slime on you or the healer blocks healing.' or 'Requires a bow and ammunition. Give both through the bag menu.'
     return H.tip('Recruit '..role,'Click to recruit if a band slot is free. '..desc),true
    end end
   end
   if name=='mercBand' then local m=ui.world.mercs[ui.selectedMerc or 1];if m then for ri,slot in ipairs({'head','body','weapon','offhand','ammo'}) do if inside(mx,my,x+18,y+164+(ri-1)*42,pw-36,34) then local it=(m.equipment or {})[slot];if it then return {item=require('game.items').equipped(m,slot)},true end end end end end
   if H.stations[name] then local ri=ui:craftRecipeAt(name,mx,my);local r=ri and ui.crafting:getRecipes(name)[ri];if r then return H.recipe(ui,name,r),true end;return H.tip(H.stations[name][1],H.stations[name][2]..' Scroll for more recipes.'),true end
   return H.tip(name,panels[name] or 'Click controls to select; right-click items for actions.'),true
  end
 end
 for i=1,4 do if inside(mx,my,ui:potionSlotRect(i,w,h)) then local n=ui.potionBelt[i];return n and {item={name=n}} or H.tip('Potion slot F'..i,'Drag a potion here or right-click one > Equip Potion. Press F'..i..' to drink. Left-click a filled slot to drink; right-click to unequip.'),true end end
 for i=1,ui.inv:bagSlotCount()do if inside(mx,my,ui:bagSlotRect(i,w,h))then local bag=ui.inv.bagSlots[i];if bag then return{item={name=bag.name,qty=1,qualityGrade=bag.qualityGrade},info=require('game.bag_system').tooltip(bag,ui.skills:get('Strength').level)},true end;return H.tip('Empty bag slot '..i,'Drag any bag here to equip it.'),true end end
 if inside(mx,my,ui:menuButtonsRect(w,h)) then return H.tip('Character controls','Equipment: E. Skills: K. Mercenaries manages your band. Unstuck (U) returns you to safety. Drag empty bar space to move it.'),true end
 return nil,false
end
function H.world(ui,x,y)
 local w=ui.world
 local object,kind=require('game.caves').at(w,x,y)
 if object then
  if kind=='entrance' then local lo,hi=require('game.level_zones').encounterRange(w.map,object.x,object.y);lo,hi=object.levelMin or lo,object.levelMax or hi;return H.tip('Cave '..object.id..' - Levels '..lo..'-'..hi,'Left-click while standing close to enter. Enemy levels '..lo..'-'..hi..'. Rats, slimes, ore and caches. Rare bosses may appear. Purple triangles mark caves on the minimap. No entry gate.') end
  if kind=='exit' then return H.tip('Cave exit','Left-click while nearby to return to the surface. Loot and mining progress are kept. Saving underground reloads safely outside.') end
  return H.tip('Cave loot cache',#object.items>0 and 'Left-click nearby to collect loot. If your bags fill, remaining items stay here.' or 'Empty. This cache has already been looted.')
 end
 local bagKeeper=require('game.bag_keeper').at(w,x,y);if bagKeeper then return H.tip('Bag Keeper','Click nearby for a free starter bag if you have no bag equipped, carried, banked, in camp storage, or recoverable in your grave or on the ground. Equips a D-grade Medium Leather Bag. Other playersâ€™ bags do not count.')end
 local st=w:stationAt(x,y)
 if st and H.stations[st] then local a=H.stations[st];return H.tip(a[1],a[2]) end
 if w:mercRecruiterAt(x,y) then return H.tip('Mercenary Recruiter','Click nearby to recruit Tank, Healer or Ranged companions. Manage gear with the Mercenaries button.') end
 if w:bankClerkAt(x,y) then return H.tip('Bank Clerk','Click nearby to view coins and buy bank slots.') end
 local v=w:tradeKeeperAt(x,y);if v then return H.tip((v.shop and v.shop.title) or 'Trader','Click nearby to trade. Right-click stock to buy, or your bag goods to sell accepted items.') end
 if w:healerAt(x,y) then return H.tip('Healer','Click nearby to restore health for 5 silver. No charge when healthy. Slime coating blocks healing.') end
 if w:bankChestAt(x,y) then return H.tip('Bank Chest','Click nearby to open storage. Left-click bag items to deposit; click stored items to withdraw. Right-click stored items for quantity withdrawals. Drag bank items between slots to sort them.') end
 local g=w:groundItemAt(x,y);if g then return H.tip(g.name,'Click to pick up. Requires bag space.','On the ground') end
 local sh=w:sheepAt(x,y);if sh then return H.tip('Sheep',sh.wool and 'Carry Shears and click nearby to collect wool.' or 'Already shorn. Wait for wool to regrow.') end
 local n=w:nodeAt(x,y);if n then if require('game.prospecting').isOre(n) then return require('game.prospecting').tooltip(ui,n) end;local d=w:resourceInfo(n.kind);if d then return H.tip(d.item,'Click nearby to auto-gather. '..(d.tool and 'Requires '..d.tool..'. ' or 'No tool required. ')..d.skill..' level '..(d.level or 1)..'.') end;return H.tip('Berry Bush','Click nearby for berries, then greens, then roots. No tool required.') end
 local c=w:animalCarcassAt(x,y);if c then return H.tip(c.kind..' carcass','Click nearby with a Copper Dagger or Copper Knife available to skin. Leave bag space for drops.') end
 local e=w:enemyAt(x,y);if e then return H.tip(e.kind..' (Lv '..e.level..')','Click to start combat. Bows need equipped ammunition. '..(e.kind=='nagaQueen'and 'World boss: head butt, tail swing and water magic. Dodge the warning circles; she rests for eight seconds between attacks. Tramples trees and hunts other creatures. Level 12.'or e.kind=='slimeBoss' and 'Avoid shots and puddles: coating slows, silences and suffocates.' or e.kind=='caveSnake' and 'Boss snake: may drop blessable fangs. Skin with a Copper Knife/Dagger for randomized hides and 2-5 meats. Cooking 25; base cooked meat heals 130 HP.' or e.kind=='gigaRat' and 'Skin for extra-large hide and meat. Meat requires Cooking 20.' or 'Keep stamina available for attacks.')..(e.nightOnly and ' Active at night.' or e.dayOnly and ' Active in daytime.' or '')) end
 for _,m in ipairs(w.mercs) do if (x-m.x)^2+(y-m.y)^2<12^2 then return H.tip(m.name,'Follows and assists in combat. Open Mercenaries to equip or dismiss.') end end
 for _,house in ipairs(w.houses) do local l,t,ww,hh=require('game.houses').bounds(house);if inside(x,y,l,t,ww,hh) then return H.tip('Village House','Services are outside. Click the nearby station or villager to interact.') end end
 for _,pool in ipairs(w.bossPools or {}) do if (x-pool.x)^2+(y-pool.y)^2<22^2 then return H.tip('Boss slime puddle','Move away. Coating halves movement, blocks magic and causes 2 damage each second. A Potent Antidote clears it.') end end
 for _,pool in ipairs(w.slimePuddles or {}) do if (x-pool.x)^2+(y-pool.y)^2<15^2 then return H.tip('Poison puddle','Move away to avoid poison. Use an antipoison potion to clear poisoning.') end end
 for _,torch in ipairs(w.standingTorches or {}) do if (x-torch.x)^2+(y-torch.y)^2<12^2 then return H.tip('Village torch','Lights the village at night. No interaction required.') end end
 for _,n in ipairs(require("game.node_index").at(w,x,y)) do if n.depleted and (x-n.x)^2+(y-n.y)^2<15^2 then if require('game.prospecting').isOre(n) then return require('game.prospecting').tooltip(ui,n) end;return H.tip('Depleted resource','Wait for this resource to regrow or replenish. No gathering is possible yet.') end end
 if (x-ui.player.x)^2+(y-ui.player.y)^2<12^2 then return H.tip('Your character','WASD to move. Keep stamina for combat and crafting. '..((ui.player.slimeCoated or 0)>0 and 'SLIMED: half speed, no magic, 1 suffocation damage per second. Use a Potent Antidote or wait for expiry.' or 'Hover items for instructions; right-click bag items for actions.')) end
 local tx,ty=math.floor(x/16)+1,math.floor(y/16)+1
 if tx>=1 and tx<=w.map.cols and ty>=1 and ty<=w.map.rows and (w.map:isBeachCell(tx,ty) or w.map:isBeachWaterCell(tx,ty)) then return H.tip('Fishing Shore','Carry a Fishing Pole and click nearby. Fishing repeats until bags fill or you walk away.') end
end
local originalUI=H.ui
function H.ui(ui,mx,my,w,h)
 local k
 if ui.panelAt then local key,x,y,pw,ph,scale=ui:panelAt(mx,my);k=key;if k then mx,my=x+(mx-x)/scale,y+(my-y)/scale end end
 if k then ui.inputPanel=k;local tip=originalUI(ui,mx,my,w,h);ui.inputPanel=nil;return tip or H.tip(k,'Use this panel to interact.'),true end
 ui.inputPanel=k;local tip,blocked=originalUI(ui,mx,my,w,h);ui.inputPanel=nil
 return tip,blocked
end
return H

